import {money,summarize,filterTransactions,recordPayment,initialTransactions,initialInvoices,monthlyFlow} from './finance.mjs';
const paths={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z',grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',arrows:'M4 7h16m-4-4 4 4-4 4M20 17H4m4-4-4 4 4 4',invoice:'M6 3h12v18l-3-2-3 2-3-2-3 2z M9 7h6M9 11h6M9 15h3',wallet:'M3 6h17v15H3z M3 6V3h14v3M16 11h5v5h-5z',chart:'M4 3v18h17M8 15V9M13 15V5M18 15v-4',card:'M3 5h18v14H3zM3 9h18M6 15h4',settings:'m9 3-1 3-3 1 1 3-2 2 2 2-1 3 3 1 1 3h6l1-3 3-1-1-3 2-2-2-2 1-3-3-1-1-3z M9 12a3 3 0 1 0 6 0 3 3 0 1 0-6 0',help:'M9 9a3 3 0 1 1 5 2c-2 1-2 2-2 3M12 17h.01M22 12a10 10 0 1 1-20 0 10 10 0 1 1 20 0',down:'m7 10 5 5 5-5',chevrons:'m8 8 4-4 4 4m-8 8 4 4 4-4',right:'m9 5 7 7-7 7',arrow:'M5 12h14m-5-5 5 5-5 5',upRight:'M6 18 18 6M6 6h12v12',downLeft:'M18 6 6 18M6 6v12h12',search:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 1 1 16 0',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4',plus:'M12 5v14M5 12h14',download:'M12 3v12m-5-5 5 5 5-5M5 16v5h14v-5',calendar:'M4 5h16v16H4zM8 3v5M16 3v5M4 11h16',filter:'M4 7h16M7 12h10M10 17h4',more:'M5 12h.01M12 12h.01M19 12h.01',info:'M12 11v6M12 7h.01M22 12a10 10 0 1 1-20 0 10 10 0 1 1 20 0',shield:'M12 3 3 6v6c0 5 9 9 9 9s9-4 9-9V6z m-4 9 3 3 5-6',menu:'M4 6h16M4 12h16M4 18h16',close:'m6 6 12 12M6 18 18 6',bank:'m3 9 9-6 9 6H3m2 3v6m7-6v6m7-6v6M3 21h18',check:'m5 12 4 4L19 6',logout:'M9 4H4v16h5M10 12h11m-4-4 4 4-4 4',copy:'M9 9h12v12H9z M15 9V3H3v12h6'};
const icon=(name)=>`<svg class="icon" aria-hidden="true" viewBox="0 0 24 24"><path d="${paths[name]||paths.grid}"/></svg>`;
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const app=document.querySelector('#app'),modal=document.querySelector('#modal');
const initial={transactions:initialTransactions,invoices:initialInvoices,business:'Studio North',name:'Abdulhalim',email:'hello@studionorth.co',frozen:false};
let data=structuredClone(initial),persist=true;
try{const saved=JSON.parse(localStorage.getItem('folio-demo-v1'));if(saved?.version===1&&Array.isArray(saved.transactions)&&Array.isArray(saved.invoices))data={...data,...saved};}catch{persist=false;}
let view='Overview',direction='all',query='',range='6',mobile=false,toastTimer;
const opening=3525800,reserve=1200000;
const operating=()=>opening+data.transactions.filter(r=>r.date.startsWith('2026-11')).reduce((s,r)=>s+r.amount,0);
const balance=()=>operating()+reserve;
const stats=()=>summarize(data.transactions,'2026-11');
const unpaid=()=>data.invoices.filter(i=>i.status!=='Paid');
function save(){try{localStorage.setItem('folio-demo-v1',JSON.stringify({...data,version:1}));}catch{persist=false;toast('Changes are kept for this session only. Browser storage is unavailable.');}}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),4200);}
const btn=(label,action,ico='',primary=false,extra='')=>`<button class="button${primary?' primary':''}" data-action="${action}" ${extra}>${ico?icon(ico):''}${label}</button>`;
const quiet=(label,action)=>`<button class="button quiet" data-action="${action}">${label}${icon('arrow')}</button>`;
const dateLabel=d=>new Date(d+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'short'});
const moneyHtml=c=>{const [whole,dec]=money(c).split('.');return `${whole}<span class="cents">.${dec}</span>`;};
function navigation(){const links=[['Overview','grid'],['Transactions','arrows'],['Invoices','invoice'],['Accounts','wallet'],['Cards','card'],['Reports','chart']];return `<aside class="sidebar${mobile?' open':''}" aria-label="Main navigation"><div class="brand"><svg viewBox="0 0 32 36" aria-hidden="true"><path d="M3 3h27v7H11v6h15v7H11v10H3z" fill="#243e2c"/><path d="M18 27h8v6h-8z" fill="#8caa91"/></svg>folio<span style="font-size:12px;align-self:flex-start;letter-spacing:0;margin:9px 0 0 -5px">®</span></div><div class="workspace"><div class="workspace-mark">n.</div><div><strong>${esc(data.business)}</strong><small>Business account</small></div><span class="chevrons">${icon('chevrons')}</span></div><p class="nav-label">Workspace</p><nav>${links.map(([v,i])=>`<a class="nav-item ${view===v?'active':''}" href="#${v.toLowerCase()}" ${view===v?'aria-current="page"':''}>${icon(i)}${v}${v==='Invoices'?`<span class="badge">${unpaid().length}</span>`:''}</a>`).join('')}</nav><div class="nav-divider"></div><a href="#Settings" class="nav-item ${view==='Settings'?'active':''}">${icon('settings')}Settings</a><div class="sidebar-bottom"><button class="nav-item" data-action="help">${icon('help')}Help & getting started${icon('upRight')}</button><div class="demo-note"><strong><span class="dot"></span>Your space to explore</strong>Demo workspace. Try a payment or create your first invoice.</div><div class="profile"><span class="avatar">${esc(data.name.slice(0,2).toUpperCase())}</span><div><strong>${esc(data.name)}</strong><small>Workspace owner</small></div><button data-action="profile" aria-label="Account settings">${icon('chevrons')}</button></div></div></aside>`;}
function header(){return `<header class="topbar"><button class="mobile-menu" data-action="menu" aria-label="Toggle navigation" aria-expanded="${mobile}">${icon('menu')}</button><div class="breadcrumb">Workspace ${icon('right')}<span>${view}</span></div><div class="top-actions"><form class="search" id="global-search">${icon('search')}<input aria-label="Search transactions" name="q" placeholder="Search anything..."><kbd class="shortcut">⌘ K</kbd></form><button class="notification" data-action="notifications" aria-label="Notifications">${icon('bell')}</button><button class="avatar" data-action="profile" aria-label="Open profile">${esc(data.name.slice(0,2).toUpperCase())}</button></div></header>`;}
function pageHeading(){const subtitles={Overview:'A clear view of your business, every day.',Transactions:'Every movement, all in one place.',Invoices:'Keep your work moving. Get paid on time.',Accounts:'A place for every part of your business.',Cards:'Your team’s spending, under control.',Reports:'Understand the story behind your numbers.',Settings:'Make this workspace yours.'};return `<div class="page-heading"><div><h1>${view==='Overview'?'Business overview':view}</h1><p>${subtitles[view]}</p></div><div class="actions">${view==='Settings'?'':btn('Export','export','download')}${['Invoices','Overview'].includes(view)?btn('Create invoice','invoice','plus',true):view==='Transactions'?btn('Make a payment','payment','upRight',true):''}</div></div>`;}
function metrics(){const s=stats(),due=unpaid().reduce((sum,i)=>sum+i.amount,0);return `<section class="metrics" aria-label="Financial summary"><div class="metric"><div class="eyebrow">Total balance ${icon('info')}</div><div class="metric-value num">${moneyHtml(balance())}</div><div class="metric-foot"><span class="dot"></span> Across 2 business accounts</div></div><div class="metric"><div class="eyebrow">Money in</div><div class="metric-value num">${moneyHtml(s.income)}</div><div class="metric-foot"><span class="positive">↙ ${data.transactions.filter(t=>t.amount>0&&t.date.startsWith('2026-11')).length} payments received</span> this month</div></div><div class="metric"><div class="eyebrow">Money out</div><div class="metric-value num">${moneyHtml(s.expenses)}</div><div class="metric-foot">1–7 November 2026</div></div><div class="metric"><div class="eyebrow">Outstanding invoices</div><div class="metric-value num">${moneyHtml(due)}</div><div class="metric-foot"><span class="overdue">${unpaid().filter(i=>i.status==='Overdue').length} overdue</span> · ${unpaid().length} awaiting payment</div></div></section>`;}
function chartPanel(){return `<section class="panel cash-chart"><div class="panel-head"><h2>Cash flow</h2><select class="select" id="chart-range" aria-label="Cash flow period"><option value="6" ${range==='6'?'selected':''}>Last 6 months</option><option value="3" ${range==='3'?'selected':''}>Last 3 months</option></select></div><div class="cash-topline"><div class="cash-amount num" id="cash-net"></div><div class="legend"><span><i></i>Money in</span><span><i></i>Money out</span></div></div><div class="chart" id="cash-chart"></div><p class="chart-note">November through 7 Nov · GBP</p></section>`;}
function accountPanel(){return `<section class="panel accounts-panel"><div class="panel-head"><h2>Your accounts</h2><button class="button quiet" data-action="accounts" aria-label="View all accounts">${icon('arrow')}</button></div><div class="account-feature"><div class="account-line"><h3>Operating account</h3><span class="currency"><i>£</i> GBP</span></div><div class="account-balance num">${money(operating())}</div><small>Available balance</small><div class="account-bottom"><span>•••• 4092</span><span>FOLIO BUSINESS</span></div></div><div class="reserve-row">${icon('bank')}<div><h3>Tax reserve</h3><small>•••• 8126</small></div><span class="num">${money(reserve)}</span></div><div class="accounts-footer">${quiet('Make a payment','payment')}</div></section>`;}
function transactionsPanel(full=false){const rows=filterTransactions(data.transactions,query,direction),shown=full?rows:rows.slice(0,5);return `<section class="panel ${full?'full-table':''}"><div class="panel-head"><h2>${full?'All transactions':'Recent transactions'}</h2>${full?'<small>GBP · All accounts</small>':quiet('View all','transactions')}</div><div class="table-toolbar"><div class="tabs" role="tablist" aria-label="Transaction type">${[['all','All transactions'],['in','Money in'],['out','Money out']].map(([v,l])=>`<button class="tab ${direction===v?'active':''}" role="tab" aria-selected="${direction===v}" data-filter="${v}">${l}</button>`).join('')}</div>${full?`<label class="filter-search">${icon('search')}<input id="transaction-search" aria-label="Filter transactions" placeholder="Search transactions" value="${esc(query)}"></label>`:btn('Filter','filter','filter')}</div><div class="table-wrap"><table><thead><tr><th>Transaction</th><th class="category-cell">Category</th><th class="date-cell">Date</th><th class="status-cell">Status</th><th class="right">Amount</th></tr></thead><tbody>${shown.length?shown.map(t=>`<tr class="click-row" data-transaction="${esc(t.id)}" tabindex="0" aria-label="View ${esc(t.name)} transaction"><td><div class="identity"><span class="merchant ${t.name==='Linear Studio'?'linear':t.name==='Figma'?'figma':''}">${esc(t.initials)}</span><div><strong>${esc(t.name)}</strong><small>${t.amount>0?'Bank transfer':'Business account'}</small></div></div></td><td class="category-cell muted">${esc(t.category)}</td><td class="date-cell muted">${dateLabel(t.date)}, 2026</td><td class="status-cell"><span class="status">Completed</span></td><td class="right num ${t.amount>0?'positive':''}">${t.amount>0?'+':'−'}${money(Math.abs(t.amount))}</td></tr>`).join(''):'<tr><td colspan="5" class="empty">No transactions match your search.</td></tr>'}</tbody></table></div><div class="transaction-footer"><span>${shown.length?`Showing ${shown.length} of ${rows.length} transactions`:'No matching transactions'}</span><span>Demo data · 7 Nov 2026</span></div></section>`;}
function invoicePanel(){return `<section class="panel invoices-panel"><div class="panel-head"><h2>Awaiting payment</h2><span class="muted" style="font-size:11px">${unpaid().length} invoices</span></div><div class="invoice-list">${unpaid().slice(0,3).map(i=>`<div class="invoice-row"><div class="invoice-top"><strong>${esc(i.client)}</strong><span class="num">${money(i.amount)}</span></div><div class="invoice-meta"><span>${i.id} · ${dateLabel(i.due)}</span><span class="status ${i.status}">${i.status}</span></div></div>`).join('')||'<p class="empty">All caught up. Every invoice is paid.</p>'}</div><div class="invoice-footer">${btn('View all invoices','invoices','invoice')}</div></section>`;}
function invoicesView(){return `<section class="panel full-table invoice-table"><div class="panel-head"><h2>Your invoices</h2><small>${data.invoices.length} total</small></div><div class="list-summary"><span><strong>${money(unpaid().reduce((s,i)=>s+i.amount,0))}</strong> outstanding</span><span><strong>${unpaid().filter(i=>i.status==='Overdue').length}</strong> overdue</span></div><div class="table-wrap"><table><thead><tr><th>Client / Invoice</th><th class="date-cell">Due date</th><th class="status-cell">Status</th><th class="right">Amount</th><th class="right">Action</th></tr></thead><tbody>${data.invoices.map(i=>`<tr><td><div class="identity"><span class="merchant">${esc(i.initials)}</span><div><strong>${esc(i.client)}</strong><small>${esc(i.id)}</small></div></div></td><td class="date-cell muted">${dateLabel(i.due)}, ${new Date(i.due+'T12:00:00').getFullYear()}</td><td class="status-cell"><span class="status ${i.status}">${i.status}</span></td><td class="right num">${money(i.amount)}</td><td class="right">${i.status==='Paid'?'<span class="muted">Paid</span>':btn('Record paid','settle','',false,`data-id="${esc(i.id)}"`)}</td></tr>`).join('')}</tbody></table></div></section>`;}
function accountsView(){return `<div class="account-grid">${[{name:'Operating account',balance:operating(),number:'4092',sort:'04-00-04',purpose:'Day-to-day income and expenses'},{name:'Tax reserve',balance:reserve,number:'8126',sort:'04-00-04',purpose:'Set aside for future tax payments'}].map(a=>`<section class="panel"><div class="account-feature"><div class="account-line"><h3>${a.name}</h3><span>GBP</span></div><div class="account-balance num">${money(a.balance)}</div><small>${a.purpose}</small><div class="account-bottom"><span>•••• ${a.number}</span><span>FOLIO BUSINESS</span></div></div><div class="account-detail"><span>Account holder</span><strong>${esc(data.business)}</strong></div><div class="account-detail"><span>Sort code</span><span>${a.sort}</span></div><div class="account-detail"><span>Status</span><span class="positive">Demo account</span></div>${a.number==='4092'?btn('Make a payment','payment','upRight'):''}</section>`).join('')}</div>`;}
function cardsView(){return `<section class="panel settings-panel"><h2>Business debit card</h2><div class="account-feature" style="max-width:360px;margin:0 0 20px"><div class="account-line"><h3>folio business</h3>${icon('card')}</div><div class="account-balance num" style="letter-spacing:3px;font-size:21px">•••• •••• •••• 4092</div><div class="account-bottom"><span>${esc(data.name.toUpperCase())}</span><span>DEBIT</span></div></div><div class="account-detail"><span>Card status</span><strong>${data.frozen?'Frozen':'Active'}</strong></div><div class="account-detail"><span>Monthly spending limit</span><span>£5,000.00</span></div><div class="account-detail"><span>Linked account</span><span>Operating account</span></div><p class="form-note" style="margin-top:18px">This is a demo card. Freezing it changes the demo status only.</p>${btn(data.frozen?'Unfreeze card':'Freeze card','freeze','shield',true)}</section>`;}
function reportsView(){const grouped={};data.transactions.filter(t=>t.amount<0&&t.date.startsWith('2026-11')).forEach(t=>grouped[t.category]=(grouped[t.category]||0)-t.amount);const total=stats().expenses;return `<div class="report-grid">${chartPanel()}<section class="panel"><div class="panel-head"><h2>Spending breakdown</h2><small>November</small></div><div class="spend-list">${Object.entries(grouped).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<div class="spend-item"><div><span>${esc(k)}</span><span class="num">${money(v)}</span></div><div class="track" role="meter" aria-label="${esc(k)} share of expenses" aria-valuenow="${Math.round(v/total*100)}" aria-valuemin="0" aria-valuemax="100"><i style="width:${v/total*100}%"></i></div></div>`).join('')}</div></section></div>`;}
function settingsView(){return `<section class="panel settings-panel"><h2>Business details</h2><form id="settings-form"><div class="form-grid"><label class="field">Business name<input required maxlength="50" name="business" value="${esc(data.business)}"></label><label class="field">Your name<input required maxlength="35" name="name" value="${esc(data.name)}"></label><label class="field full">Contact email<input type="email" required name="email" value="${esc(data.email)}"></label></div><p class="form-note">Changes are saved in this browser. This demo isn’t connected to a bank or accounting service.</p>${btn('Save changes','save-settings','check',true,'type="submit"')}</form><div class="nav-divider" style="margin:28px 0"></div><h2>Demo workspace</h2><p class="form-note">Restore the sample transactions, invoices and business details.</p>${btn('Reset demo data','reset')}</section>`;}
function render(){app.innerHTML=`${navigation()}<main class="main">${header()}<div class="content">${pageHeading()}${view==='Overview'?`${metrics()}<div class="dashboard-grid"><div class="left-stack">${chartPanel()}${transactionsPanel()}</div><div class="right-stack">${accountPanel()}${invoicePanel()}</div></div>`:view==='Transactions'?transactionsPanel(true):view==='Invoices'?invoicesView():view==='Accounts'?accountsView():view==='Cards'?cardsView():view==='Reports'?reportsView():settingsView()}<footer class="bottom-note"><span>${icon('shield')} Demo workspace · ${persist?'Changes saved in this browser':'Session only'}</span><span>Made for the way you do business.</span></footer></div></main>`;drawChart();}
function drawChart(){const el=document.querySelector('#cash-chart');if(!el)return;const s=stats();const flow=[...monthlyFlow,{name:'Nov',income:s.income/100,expenses:s.expenses/100}].slice(-Number(range));document.querySelector('#cash-net').innerHTML=`${money(Math.round(flow.reduce((sum,r)=>sum+r.income-r.expenses,0)*100))}<small>Net cash flow over ${range} months</small>`;if(window.Charts){window.Charts.line(el,{labels:flow.map(r=>r.name),series:[{name:'Money in',values:flow.map(r=>r.income)},{name:'Money out',values:flow.map(r=>r.expenses)}],format:v=>money(Math.round(v*100)),tickFormat:v=>`£${v/1000}k`,yTicks:[0,10000,20000,30000,40000]});}else setTimeout(drawChart,100);}
function navigate(next){view=next;mobile=false;query='';direction='all';render();window.scrollTo(0,0);}
function route(){const raw=location.hash.slice(1).toLowerCase();const found=['Overview','Transactions','Invoices','Accounts','Cards','Reports','Settings'].find(v=>v.toLowerCase()===raw);navigate(found||'Overview');}
window.addEventListener('hashchange',route);
let opener=null;
function showModal(title,body){opener=document.activeElement;modal.innerHTML=`<div class="modal-head"><h2 id="modal-title">${title}</h2><button class="close" data-action="close" aria-label="Close dialog">${icon('close')}</button></div>${body}`;modal.showModal();}
modal.addEventListener('close',()=>opener?.isConnected&&opener.focus());
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close();}});
function invoiceModal(){showModal('Create an invoice',`<p class="form-note">Add an invoice to your demo workspace. No email will be sent.</p><form id="invoice-form"><label class="field">Client name<input name="client" required maxlength="60" placeholder="e.g. Morrow Studio" autofocus></label><label class="field">Description<input name="description" required maxlength="100" placeholder="What’s the invoice for?"></label><div class="form-grid"><label class="field">Amount (GBP)<input name="amount" type="number" min="0.01" max="1000000" step="0.01" required placeholder="0.00"></label><label class="field">Due date<input name="due" type="date" required value="2026-11-21" min="2026-01-01" max="2030-12-31"></label></div><p class="error" id="form-error" role="alert"></p><div class="modal-actions">${btn('Cancel','close','',false,'type="button"')}<button class="button primary" type="submit">Create invoice</button></div></form>`);}
function paymentModal(){showModal('Make a demo payment',`<p class="form-note">Record an outgoing payment in your workspace. No real money moves.</p><form id="payment-form"><label class="field">Pay from<select><option>Operating account · ${money(operating())}</option></select></label><label class="field">Recipient<input name="recipient" required maxlength="60" placeholder="Person or business name"></label><label class="field">Amount (GBP)<input name="amount" type="number" min="0.01" max="${operating()/100}" step="0.01" required placeholder="0.00"></label><p class="error" id="form-error" role="alert"></p><div class="modal-actions">${btn('Cancel','close','',false,'type="button"')}<button class="button primary" type="submit">Record payment ${icon('upRight')}</button></div></form>`);}
function exportCsv(){let rows,filename;if(view==='Invoices'){rows=[['Invoice','Client','Due date','Status','Amount GBP'],...data.invoices.map(i=>[i.id,i.client,i.due,i.status,i.amount/100])];filename='folio-invoices.csv';}else{rows=[['ID','Transaction','Date','Category','Amount GBP'],...filterTransactions(data.transactions,query,direction).map(t=>[t.id,t.name,t.date,t.category,t.amount/100])];filename='folio-transactions.csv';}const csv=rows.map(r=>r.map(v=>{let s=typeof v==='number'?v.toFixed(2):String(v);if(typeof v==='string'&&/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';}).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Your CSV export is ready.');}
document.addEventListener('click',e=>{const target=e.target.closest('[data-action],[data-filter],[data-transaction]');if(!target)return;if(target.dataset.filter){direction=target.dataset.filter;render();return;}if(target.dataset.transaction){const t=data.transactions.find(t=>t.id===target.dataset.transaction);showModal('Transaction details',`<div class="detail-amount num ${t.amount>0?'positive':''}">${t.amount>0?'+':'−'}${money(Math.abs(t.amount))}</div>${[['Business',t.name],['Transaction ID',t.id],['Date',dateLabel(t.date)+' 2026'],['Category',t.category],['Status','Completed']].map(([k,v])=>`<div class="detail-row"><span class="muted">${k}</span><strong>${esc(v)}</strong></div>`).join('')}<p class="form-note" style="margin-top:20px">This is a demo transaction.</p>`);return;}const action=target.dataset.action;if(['transactions','invoices','accounts'].includes(action)){location.hash=action;return;}switch(action){case'menu':mobile=!mobile;render();break;case'close':modal.close();break;case'profile':location.hash='settings';break;case'invoice':invoiceModal();break;case'payment':paymentModal();break;case'export':exportCsv();break;case'filter':showModal('Filter transactions',`<form id="filter-form"><label class="field">Search name or category<input name="q" value="${esc(query)}" placeholder="e.g. Software"></label><label class="field">Payment type<select name="direction"><option value="all">All transactions</option><option value="in" ${direction==='in'?'selected':''}>Money in</option><option value="out" ${direction==='out'?'selected':''}>Money out</option></select></label><div class="modal-actions">${btn('Cancel','close','',false,'type="button"')}<button class="button primary" type="submit">Apply filters</button></div></form>`);break;case'notifications':showModal('You’re up to date',`<div class="notification-row">${unpaid().filter(i=>i.status==='Overdue').length} overdue invoice${unpaid().filter(i=>i.status==='Overdue').length===1?'':'s'} need attention<small>Review your invoices to keep cash moving.</small></div><div class="notification-row">Your November overview is ready<small>Demo snapshot · 7 November 2026</small></div><div class="modal-actions">${btn('View invoices','go-invoices')}</div>`);break;case'go-invoices':modal.close();location.hash='invoices';break;case'help':showModal('Welcome to Folio',`<p class="form-note">Your business finances, in focus.</p><div class="notification-row"><strong>Get the whole picture</strong><small>Explore cash flow, account balances and recent activity on the overview.</small></div><div class="notification-row"><strong>Try your daily workflow</strong><small>Create invoices, record a demo payment, or export your transactions as a CSV.</small></div><div class="notification-row"><strong>Make it yours</strong><small>Change the workspace details in Settings. Demo changes stay in this browser; no money moves and no emails are sent.</small></div>`);break;case'freeze':data.frozen=!data.frozen;save();render();toast(data.frozen?'Demo card frozen.':'Demo card is active.');break;case'settle':{const invoice=data.invoices.find(i=>i.id===target.dataset.id);showModal('Record invoice payment',`<p class="form-note">Mark ${esc(invoice.id)} from ${esc(invoice.client)} as paid and add ${money(invoice.amount)} to your demo operating account.</p><div class="modal-actions">${btn('Cancel','close')}${btn('Record payment','confirm-settle','check',true,`data-id="${esc(invoice.id)}"`)}</div>`);break;}case'confirm-settle':{const invoice=data.invoices.find(i=>i.id===target.dataset.id);if(invoice&&invoice.status!=='Paid'){invoice.status='Paid';data.transactions.unshift({id:crypto.randomUUID(),name:invoice.client,initials:invoice.initials,amount:invoice.amount,date:'2026-11-07',category:'Client payment',status:'Completed'});save();modal.close();render();toast('Invoice marked paid. Account balance updated.');}break;}case'reset':showModal('Reset this demo?',`<p class="form-note">This restores the sample workspace and removes invoices, payments and settings you’ve added here.</p><div class="modal-actions">${btn('Cancel','close')}${btn('Reset workspace','confirm-reset','',true)}</div>`);break;case'confirm-reset':data=structuredClone(initial);save();modal.close();render();toast('Demo workspace restored.');break;}});
document.addEventListener('submit',e=>{const form=e.target;e.preventDefault();const values=Object.fromEntries(new FormData(form));if(form.id==='global-search'){view='Transactions';query=values.q;direction='all';history.replaceState(null,'','#transactions');render();return;}if(form.id==='filter-form'){query=values.q;direction=values.direction;modal.close();render();return;}if(form.id==='settings-form'){if(!values.name.trim()||!values.business.trim())return;data={...data,name:values.name.trim(),business:values.business.trim(),email:values.email.trim()};save();render();toast('Workspace details saved.');return;}try{if(form.id==='invoice-form'){const amount=Math.round(Number(values.amount)*100);if(!values.client.trim()||!values.description.trim()||!Number.isSafeInteger(amount)||amount<=0||amount>100000000)throw new Error('Enter a client, description and valid positive amount.');const next=Math.max(...data.invoices.map(i=>Number(i.id.split('-')[1])))+1;data.invoices.unshift({id:'INV-'+String(next).padStart(4,'0'),client:values.client.trim(),initials:values.client.trim().slice(0,2).toUpperCase(),description:values.description.trim(),amount,due:values.due,status:values.due<'2026-11-07'?'Overdue':'Pending'});save();modal.close();render();toast('Invoice created and saved to your demo workspace.');}if(form.id==='payment-form'){data.transactions=recordPayment(data.transactions,operating(),values.recipient,Math.round(Number(values.amount)*100));save();modal.close();render();toast('Demo payment recorded. Your balance is updated.');}}catch(err){document.querySelector('#form-error').textContent=err.message;}});
document.addEventListener('change',e=>{if(e.target.id==='chart-range'){range=e.target.value;drawChart();}});
document.addEventListener('input',e=>{if(e.target.id==='transaction-search'){const pos=e.target.selectionStart;query=e.target.value;render();const input=document.querySelector('#transaction-search');input.focus();input.setSelectionRange(pos,pos);}});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();document.querySelector('#global-search input')?.focus();}if(e.key==='Enter'&&e.target.dataset.transaction)e.target.click();if(e.key==='Escape'&&mobile){mobile=false;render();}});
let resizeTimer;window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(drawChart,150);});
route();
